# Phase 3 — Nightly weekly rating summary

Makes: a fourth nightly job writes `exports/agent-rating-summary.json` — each agent's rating
count and average score over the past seven days.
Check: `npm test` passes, including the new `test/agent-rating-summary.test.js`.
Blocked by: Phase 2 (there is nothing to summarise until tickets can be rated).
Gate: ACT (one new job file mirroring an existing one, one new test file, one README line).

## Context

- `src/jobs/export-tickets.js` is the only existing nightly export; this job follows its shape
  exactly (an options bag with `now`/`dir`, `fs.mkdirSync` then `fs.writeFileSync` of pretty JSON,
  returning `{ file, ... }`).
- `src/jobs/close-resolved.js` and `src/jobs/purge-closed.js` both use the same windowing idiom:
  `if (now - timestamp < N * DAY) continue;` to mean "still inside the window, skip it for now" —
  Phase 3's 7-day cutoff follows that idiom (see `plan.md`'s assumption on the boundary).
- Destination and shape are Validation Q2 in `plan.md`: `exports/agent-rating-summary.json`,
  one row per agent.
- A rating with no owner (Validation Q3 in Phase 2) cannot be attributed to an agent and is
  skipped here the same way.

## Files

- Create `src/jobs/agent-rating-summary.js`.
- Create `test/agent-rating-summary.test.js`.
- Modify `README.md`: list the new job alongside the other three.

## Steps

- [ ] 1. Write `test/agent-rating-summary.test.js` in full:

  ```js
  'use strict';
  const test = require('node:test');
  const assert = require('node:assert/strict');
  const fs = require('node:fs');
  const os = require('node:os');
  const path = require('node:path');
  const { createStore } = require('../src/store');
  const { createTicket, assignTicket, resolveTicket } = require('../src/tickets');
  const portal = require('../src/portal');
  const { agentRatingSummary } = require('../src/jobs/agent-rating-summary');

  const DAY = 24 * 60 * 60 * 1000;
  const today = (daysAgo) => new Date(Date.UTC(2026, 0, 17) - daysAgo * DAY);
  const acme = { id: 7, orgId: 1 };

  function ratedTicket(store, score, ratedDaysAgo) {
    const t = createTicket(store, { orgId: 1, customerId: 7, subject: 'x', body: 'x', now: today(20) });
    assignTicket(store, t.id, 41);
    resolveTicket(store, t.id, 41, { now: today(19) });
    portal.rate(store, acme, t.id, score, { now: today(ratedDaysAgo) });
    return t;
  }

  test('the weekly summary counts ratings from the past seven days and averages them', () => {
    const store = createStore();
    ratedTicket(store, 5, 1);
    ratedTicket(store, 4, 2);
    ratedTicket(store, 1, 3);
    ratedTicket(store, 5, 8); // eight days old, not counted

    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'helpdesk-rating-'));
    try {
      const out = agentRatingSummary(store, { now: today(0), dir });
      const rows = JSON.parse(fs.readFileSync(out.file, 'utf8'));
      assert.deepEqual(rows, [{ owner_id: 41, ratings: 3, average: 3.33 }]);
    } finally {
      fs.rmSync(dir, { recursive: true, force: true });
    }
  });

  test('a rating with no owner is not attributed to any agent', () => {
    const store = createStore();
    const t = createTicket(store, { orgId: 1, customerId: 7, subject: 'x', body: 'x', now: today(20) });
    resolveTicket(store, t.id, 1, { now: today(19) });
    portal.rate(store, acme, t.id, 2, { now: today(1) });

    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'helpdesk-rating-'));
    try {
      const out = agentRatingSummary(store, { now: today(0), dir });
      assert.deepEqual(out.rows, []);
    } finally {
      fs.rmSync(dir, { recursive: true, force: true });
    }
  });
