  'use strict';
  // Nightly. Writes exports/agent-rating-summary.json: for each agent, how many ratings their
  // tickets received in the past seven days, and the average score.
  const fs = require('node:fs');
  const path = require('node:path');

  const EXPORT_DIR = path.join(__dirname, '..', '..', 'exports');
  const WINDOW_DAYS = 7;
  const DAY = 24 * 60 * 60 * 1000;

  function agentRatingSummary(store, { now = new Date(), dir = EXPORT_DIR } = {}) {
    const totals = new Map();
    for (const t of store.listTickets()) {
      if (t.rating_score == null || !t.owner_id) continue;
      if (now.getTime() - new Date(t.rated_at).getTime() >= WINDOW_DAYS * DAY) continue;
      const agg = totals.get(t.owner_id) || { ratings: 0, sum: 0 };
      agg.ratings += 1;
      agg.sum += t.rating_score;
      totals.set(t.owner_id, agg);
    }
    const rows = [...totals.entries()].map(([owner_id, { ratings, sum }]) => ({
      owner_id,
      ratings,
      average: Math.round((sum / ratings) * 100) / 100,
    }));
    fs.mkdirSync(dir, { recursive: true });
    const file = path.join(dir, 'agent-rating-summary.json');
    fs.writeFileSync(file, JSON.stringify(rows, null, 2) + '\n');
    return { file, rows };
  }

  module.exports = { agentRatingSummary, WINDOW_DAYS };
  ```

  Evidence: the file as written above, saved at `src/jobs/agent-rating-summary.js`.

